from __future__ import annotations


from .qwen3_hf_generate import is_cuda_oom, is_hip_invalid_value
_FAIL_FAST_SAME = 3


def _is_cuda_oom(err: BaseException) -> bool:
    return is_cuda_oom(err)


def _is_systemic_qwen_error(err: BaseException) -> bool:
    """Errors that will not recover on the next window/batch."""
    if _is_cuda_oom(err):
        return True
    # HIP invalid-argument on one batch is often recoverable after split / float32;
    # do not abort the whole film on the first hit.
    if is_hip_invalid_value(err):
        return False
    msg = str(err or "").lower()
    needles = (
        "numba needs numpy",
        "no module named",
        "cannot import",
        "dll load failed",
        "no kernel image",
        "cudaerrornokernelimagefordevice",
        "invalid device",
        "device-side assert",
        "cudnn",
        "cublas",
        "winerror 999",
        "expected all tensors to be on the same device",
        "not enough memory",
        "paging file",
    )
    if any(n in msg for n in needles):
        return True
    if "cuda error" in msg or "hip error" in msg:
        return True
    return False


def _qwen_error_text(err: BaseException | None) -> str:
    if err is None:
        return "unknown error"
    msg = str(err).strip() or type(err).__name__
    if _is_cuda_oom(err):
        return (
            f"{msg}。显存不足：请关闭占用显卡的本地大模型后重试，"
            "或改用 Qwen3-ASR 0.6B / Anime Whisper。"
        )
    low = msg.lower()
    compact = low.replace(" ", "")
    if "hiperrorinvalidimage" in compact or "device kernel image is invalid" in low:
        return (
            f"{msg}。AMD ROCm 缺少本卡架构的 GPU 内核包（amd-torch-device-gfx*）。"
            "请在环境检测一键修复 ROCm：必须安装 torch[device-gfx…]，"
            "不要只装 torch==x+rocm（约 114MB、无 HIP kernel）。"
            "HSA_OVERRIDE_GFX_VERSION 不能替代该内核包。"
        )
    if "no kernel image" in low or "cudaerrornokernelimagefordevice" in low:
        return (
            f"{msg}。本机显卡（如 RTX 50 系 Blackwell）需要 CUDA 12.8+ / 13.x 版 PyTorch（cu128 或 cu130），"
            "请在设置中「补齐 CUDA PyTorch」或手动安装匹配版本的 torch / torchaudio；"
            "也可暂时改用 CPU 或 anime-whisper ASR。"
        )
    if is_hip_invalid_value(err):
        return (
            f"{msg}。AMD ROCm 上 Qwen3 推理内核报错（常见于 RDNA4 / RX 9070）。"
            "请完全退出并重开 Transub 后再试（引擎会用 float32 + 单帧 greedy）；"
            "若仍失败可暂时改推理设备为 CPU，或改用 SenseVoice / Anime Whisper。"
        )
    if "autoprocessor" in low and "requirements defined correctly" in low:
        return (
            "Qwen3-ASR 加载 Processor 失败：多为引擎内 torchvision 与 ROCm PyTorch 版本不匹配。"
            "请在设置「环境检测」点一键修复，完全退出 Transub 后重试。"
        )
    if "torchvision::nms" in low or ("torchvision" in low and "nms" in low):
        return (
            "引擎内 torchvision 与 PyTorch 不匹配（常见于 AMD ROCm 一键修复后混装）。"
            "请在环境检测中一键修复，或手动重装匹配的 ROCm torch/torchvision，然后重启 Transub。"
        )
    return msg[:500]


def _qwen_fail_fast(
    *,
    err: BaseException,
    first_err: BaseException | None,
    same_streak: int,
) -> bool:
    if _is_systemic_qwen_error(err) or _is_systemic_qwen_error(first_err or err):
        return True
    return same_streak >= _FAIL_FAST_SAME
